#!/usr/bin/env python3
"""Builds THIRD-PARTY-LICENSES.md from the Maven and npm license scans and enforces the license policy.

Usage: third-party-licenses.py <licenses.xml> <npm-licenses.json> <output.md>

  licenses.xml        written by license-maven-plugin (aggregate-download-licenses)
  npm-licenses.json   written by license-checker (--production --json)

Exits 1 if a component has no acceptable license, so a release cannot ship one unnoticed.
A component passes if at least one of its license alternatives is acceptable. Alternatives are
separated by OR (npm) or by " / " (Maven lists every license a POM declares as an alternative).
"""
import json
import re
import sys
import xml.etree.ElementTree as ET

# Strong or network copyleft: never acceptable, not even with a classpath exception.
ALWAYS_DENIED = re.compile(r"AGPL|Affero|SSPL|Commons Clause|BUSL|Business Source", re.I)
# GPL/LGPL are acceptable only as an extra option or with the Classpath Exception.
COPYLEFT = re.compile(r"(^|[^A-Za-z])L?GPL|General Public License", re.I)
CLASSPATH_EXCEPTION = re.compile(r"classpath exception|CPE", re.I)
UNKNOWN = re.compile(r"^(NOT DECLARED|UNLICENSED|UNKNOWN|None)$", re.I)

# Components whose license metadata is missing but whose license has been confirmed manually.
# Add an entry only after verifying the license at the source, and say how.
CONFIRMED = {
    # Cumulocity Microservice SDK: module POMs declare no license; the parent POM declares MIT.
    # https://github.com/Cumulocity-IoT/cumulocity-clients-java/blob/develop/pom.xml#L73
    # Drop this entry once the module POMs declare it.
    "com.nsn.cumulocity.clients-java:": "MIT License (Cumulocity Microservice SDK, declared in the parent POM; confirmed manually)",
}


def acceptable(alternative: str) -> bool:
    parts = [p.strip(" ()") for p in re.split(r"\s+AND\s+", alternative)]  # AND: all must pass
    for p in parts:
        if UNKNOWN.match(p) or ALWAYS_DENIED.search(p):
            return False
        if COPYLEFT.search(p) and not CLASSPATH_EXCEPTION.search(p):
            return False
    return True


def passes(expression: str) -> bool:
    alternatives = re.split(r"\s+OR\s+|\s+/\s+", expression)
    return any(acceptable(a) for a in alternatives)


def main(xml_path: str, npm_path: str, out_path: str) -> int:
    rows_java, rows_npm, violations = {}, {}, []

    for dep in ET.parse(xml_path).getroot().findall(".//dependency"):
        g, a, v = dep.findtext("groupId"), dep.findtext("artifactId"), dep.findtext("version")
        names = [n for n in (l.findtext("name") for l in dep.findall(".//license")) if n]
        lic = " / ".join(names)
        if not lic:
            lic = next((txt for prefix, txt in CONFIRMED.items() if f"{g}:".startswith(prefix)), "NOT DECLARED")
        rows_java[(g, a, v)] = lic

    for key, info in json.load(open(npm_path)).items():
        name, version = key.rsplit("@", 1)
        if name == "dynamic-mapper":  # this project, not a third party
            continue
        lic = info.get("licenses")
        lic = " OR ".join(lic) if isinstance(lic, list) else str(lic)
        rows_npm[(name, version)] = lic

    for (g, a, v), lic in rows_java.items():
        if not passes(lic):
            violations.append(f"{g}:{a}:{v} -> {lic}")
    for (n, v), lic in rows_npm.items():
        if not passes(lic):
            violations.append(f"{n}@{v} -> {lic}")

    out = [
        "# Third-party licenses", "",
        "This file lists the third-party components that Cumulocity Dynamic Mapper redistributes or "
        "depends on at runtime, with the license each one declares. It is generated by "
        "`.github/scripts/generate-third-party-licenses.sh` (Maven `license-maven-plugin` for the "
        "backend, `license-checker` for the UI, production dependencies only) and regenerated on "
        "every release. Do not edit it by hand.", "",
        "Dynamic Mapper itself is licensed under the Apache License 2.0 "
        "(see [LICENSE](LICENSE) and [NOTICE](NOTICE)).", "",
        "## Backend (Java, dynamic-mapper-service)", "",
        "| Component | Version | License |", "|---|---|---|",
    ]
    out += [f"| {g}:{a} | {v} | {lic} |" for (g, a, v), lic in sorted(rows_java.items())]
    out += ["", "## Frontend (npm, dynamic-mapper-ui)", "", "| Component | Version | License |", "|---|---|---|"]
    out += [f"| {n} | {v} | {lic.replace('|', '/')} |" for (n, v), lic in sorted(rows_npm.items())]
    open(out_path, "w").write("\n".join(out) + "\n")

    print(f"{len(rows_java)} backend and {len(rows_npm)} frontend components written to {out_path}")
    if violations:
        print("::error::Components without an acceptable license:", file=sys.stderr)
        for v in violations:
            print(f"  {v}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    if len(sys.argv) != 4:
        sys.exit(__doc__)
    sys.exit(main(*sys.argv[1:]))
